import {MIX_TEMPLATES,MASTER_TEMPLATES,validateTemplate,applyMixTemplate,applyMasterTemplate} from './mix-master-templates.js';
import {VOX_STUDIORACKS} from './vox-studioracks.js';
import {EFFECTS,INSERT_COUNT,ensurePlugins} from './plugins.js';
import {MASTER_MODULES} from './mastering.js';
export const STAGES=['premix','mix','master','export'];
export const SOURCES=['Lead Vocal','Backing Vocal','Adlibs','Baby Voice','Guitar','Bass','808','Keys','Synth','Strings','Wind','Drums','Percussion','Log Drum','Bus','Master','Other'];
export const makeRack=(id,name,genre,source,stage,chain,description=name)=>({id,name,genre,source,stage,category:source,description,stages:chain.map(([id,values])=>({id,values}))});
const sourceOf=t=>{const s=(t.id+' '+t.name).toLowerCase();if(/808/.test(s))return '808';if(/adlib/.test(s))return 'Adlibs';if(/baby/.test(s))return 'Baby Voice';if(/backing|harmon|choir|chœur/.test(s))return 'Backing Vocal';if(/lead|vocal|vox|voice/.test(s)&&t.category!=='Bus')return 'Lead Vocal';if(t.genre&&t.category===t.genre)return 'Lead Vocal';return ({Voix:'Lead Vocal',Guitares:'Guitar',Basse:'Bass',Batterie:'Drums',Instruments:'Other',Bus:'Bus',Master:'Master'})[t.category]||'Other';};
export const BASE_RACKS=Object.freeze([...MIX_TEMPLATES.map(t=>({...t,id:'mix-'+t.id,source:sourceOf(t),stage:'mix'})),...Object.entries(VOX_STUDIORACKS).filter(([,p])=>p.category!=='Master').map(([id,p])=>({...p,id:'vox-'+id,genre:p.genre||'Tous',source:sourceOf({...p,id}),stage:'mix'})),...MASTER_TEMPLATES.map(t=>({...t,id:'master-'+t.id,source:'Master',stage:'master'}))]);
export function validateRack(r){if(!r||!STAGES.includes(r.stage)||!SOURCES.includes(r.source)||r.stage==='export')throw Error('Rack audio invalide');if((r.stage==='master')!==(r.source==='Master'))throw Error('Destination incompatible');return validateTemplate(r,r.stage==='master'?'master':'mix');}
export function rackStages(r){validateRack(r);const master=r.stage==='master',registry=master?MASTER_MODULES:EFFECTS;return (r.stages||Object.entries(r.settings).filter(([id,v])=>registry[id]&&v.enabled).map(([id,v])=>({id,values:Object.fromEntries(Object.entries(v).filter(([k])=>k!=='enabled'))}))).map(s=>({id:s.id,name:registry[s.id].name,values:{...s.values}}));}
export function matchesTarget(r,track){if(r.stage==='master')return !track;if(!track)return false;if(track.type==='bus')return r.source==='Bus';if(r.source==='Bus'||r.source==='Master')return false;if(track.type==='drums')return ['Drums','Percussion','Log Drum','Other'].includes(r.source);if(track.type!=='audio'&&['Lead Vocal','Backing Vocal','Adlibs','Baby Voice'].includes(r.source))return false;return true;}
export function planRack(r,{track=null,project=null,mode='replace'}={}){validateRack(r);if(!matchesTarget(r,track)||!['replace','append'].includes(mode)||r.stage==='master'&&(!project||mode!=='replace'))throw Error('Destination ou mode incompatible');const stages=rackStages(r);let available=INSERT_COUNT;if(track&&mode==='append'){const draft=structuredClone(track);ensurePlugins(draft);available=draft.inserts.filter(x=>x===null).length;}if(stages.length>available)throw Error('Pas assez d’inserts libres');return {id:r.id,mode,stages,available};}
export function applyRack(r,{track=null,project=null,mode='replace'}={}){planRack(r,{track,project,mode});if(r.stage==='master'){const draft={mastering:structuredClone(project.mastering)};applyMasterTemplate(draft,r);project.mastering=draft.mastering;}else{const draft=structuredClone(track);applyMixTemplate(draft,{...r,stages:r.stages.map(s=>({...s,values:{...Object.fromEntries(EFFECTS[s.id].controls.map(c=>[c.key,c.default])),...s.values}}))},{mode});track.inserts=draft.inserts;track.effects=draft.effects;}return r.name;}
